package org.apache.commons.lang.time;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for org.apache.commons.lang.time.StopWatch#stop()
 */
public class StopWatch_stop_TriageGen2Test {

    @Test
    public void testStop_WhenRunning_ShouldStopSuccessfully() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();

        // Verify state is running (implicitly by not throwing exception)
        stopWatch.stop();

        // Since we cannot access private fields directly, we verify behavior
        // A stopped stopwatch should return the elapsed time
        Assert.assertTrue(stopWatch.getTime() >= 0);
    }

    @Test
    public void testStop_WhenSuspended_ShouldStopSuccessfully() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.suspend();

        // Verify stop works when in suspended state
        stopWatch.stop();

        Assert.assertTrue(stopWatch.getTime() >= 0);
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_WhenNotStarted_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        // State is STATE_STOPPED by default (or not RUNNING/SUSPENDED)
        stopWatch.stop();
    }

    @Test(expected = IllegalStateException.class)
    public void testStop_AfterStop_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.stop();

        // Second call should throw exception because state is now STATE_STOPPED
        stopWatch.stop();
    }

    @Test
    public void testStop_AfterReset_ShouldThrowIllegalStateException() {
        StopWatch stopWatch = new StopWatch();
        stopWatch.start();
        stopWatch.reset();

        // Reset sets state back to STOPPED, so stop() should fail
        try {
            stopWatch.stop();
            Assert.fail("Expected IllegalStateException to be thrown");
        } catch (IllegalStateException e) {
            Assert.assertEquals("Stopwatch is not running. ", e.getMessage());
        }
    }
}
